draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(2*t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 80 + 30 * Math.sin(3*t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Growth', W/2, H/2 - 60 + 20 * Math.sin(t));
  ctx.fillText('Discomfort', W/2, H/2 + 20 * Math.sin(2*t));
  ctx.fillText('Necessary', W/2, H/2 + 60 + 30 * Math.sin(3*t));
  ctx.restore();
}
